<body>
    <div class="inner-voice-wrapper">
        <div class="inner-voice-container" id="voiceContainer">
            <div class="flower-decoration-top">
                <span class="petal">🌸</span>
                <span class="petal">💮</span>
                <span class="petal">🌺</span>
            </div>
            <div class="flower-decoration-bottom">
                <span class="petal">🏵️</span>
                <span class="petal">🌷</span>
            </div>
            <div class="voice-title">心 声</div>
            <hr class="voice-divider">
            <div id="voiceContent">
                <div class="loading">🌸 心绪轻绽...</div>
            </div>
        </div>
    </div>

    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                console.error("无法获取消息内容");
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 提取inner标签内容 ========== */
        function extractInnerContent(messageText) {
            var match = messageText.match(/<inner>([\s\S]*?)<\/inner>/);
            if (match && match[1]) {
                return match[1].trim();
            }
            return null;
        }

        /* ========== 解析心声条目 ========== */
        function parseVoiceItems(content) {
            var items = [];
            if (!content) return items;

            var lines = content.split('\n');
            var pattern = /^\[(.+?)[：:](.+?)\.?\]$/;

            lines.forEach(function(line) {
                var trimmed = line.trim();
                if (!trimmed) return;
                var match = trimmed.match(pattern);
                if (match) {
                    items.push({
                        name: match[1].trim(),
                        text: match[2].trim()
                    });
                }
            });

            return items;
        }

        /* ========== 花蕊标记数组 ========== */
        var markerSymbols = ['❀', '✿', '🌺', '💮', '🏵️', '🌷', '🌼', '🪷', '⚘', '✾'];

        /* ========== 渲染界面 ========== */
        function renderVoicePage(items) {
            var contentEl = document.getElementById('voiceContent');

            if (!items || items.length === 0) {
                contentEl.innerHTML = '<div class="loading">💮 此间无声...</div>';
                return;
            }

            var html = '';
            items.forEach(function(item, index) {
                var marker = markerSymbols[index % markerSymbols.length];
                /* 确保文本以句号结尾 */
                var text = item.text;
                if (text && !/[。！？.!?」』）\)]$/.test(text)) {
                    text += '。';
                }

                html += '<div class="voice-item">';
                html += '<span class="voice-marker">' + marker + '</span>';
                html += '<span class="voice-text">';
                html += '<span class="voice-name">' + item.name + '</span>';
                html += '：' + text;
                html += '</span>';
                html += '</div>';
            });

            contentEl.innerHTML = html;
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('voiceContent').innerHTML =
                        '<div class="loading">🌺 花笺未展...</div>';
                    return;
                }
                var innerContent = extractInnerContent(messageText);
                var items = parseVoiceItems(innerContent);
                renderVoicePage(items);
            } catch (error) {
                console.error("心声栏错误:", error);
                document.getElementById('voiceContent').innerHTML =
                    '<div class="loading">🍂 花落无声...</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>
